from mlmodelscope.pytorch_agent.models.pytorch_abc import PyTorchAbstractClass
import open_clip
import torch
from PIL import Image

class PyTorch_Transformers_CLIP_ViT_B_32_DataComp(PyTorchAbstractClass):
    def __init__(self, config=None):
        self.config = config if config else dict()
        self.device = self.config.pop("_device", "cpu")
        multi_gpu = self.config.pop("_multi_gpu", False)

        model_id = 'hf-hub:laion/CLIP-ViT-B-32-DataComp.XL-s13B-b90K'
        
        try:
             self.model, self.preprocessor = open_clip.create_model_from_pretrained(model_id)
        except Exception as e:
             raise ImportError(f"Failed to load OpenCLIP model: {e}")
             
        self.tokenizer = open_clip.get_tokenizer(model_id)

        self.model.to(self.device)
        self.model.eval()

        self.features = self.config.get("labels",[])

        if not self.features or not isinstance(self.features, list):
            # Download and prepare ImageNet class labels for zero-shot classification
            features_file_url = "http://s3.amazonaws.com/store.carml.org/synsets/imagenet/synset.txt"
            self.features = self.features_download(features_file_url)
        
        # Pre-tokenize labels
        text_labels = [f"a photo of a {label}" for label in self.features]
        # Tokenize and move to device
        text_tokens = self.tokenizer(text_labels)
        
        # We can pre-compute text features here but since we have many labels (1000), 
        # let's be careful about memory. But for ImageNet (1000 classes), it's fine.
        # Moving all tokens to GPU might be a bit much if batch size is large, but for 1000 labels it's ok.
        text_tokens = text_tokens.to(self.device)
        
        with torch.no_grad():
             self.text_features = self.model.encode_text(text_tokens)
             self.text_features /= self.text_features.norm(dim=-1, keepdim=True)

    def to(self, device, multi_gpu=False):
        self.model.to(device)
        self.device = device

    def preprocess(self, input_images):
        processed_images = [
            self.preprocessor(Image.open(image_path).convert('RGB'))
            for image_path in input_images
        ]
        model_input = torch.stack(processed_images)
        return model_input

    def predict(self, model_input):
        model_input = model_input.to(self.device)
        
        with torch.no_grad():
            image_features = self.model.encode_image(model_input)
            image_features /= image_features.norm(dim=-1, keepdim=True)
            
            # Use the model's learned temperature parameter
            logit_scale = self.model.logit_scale.exp()
            
            # Calculate cosine similarity
            logits = logit_scale * image_features @ self.text_features.T
            
        return logits

    def postprocess(self, model_output):
        probabilities = torch.nn.functional.softmax(model_output, dim=1)
        return probabilities.tolist()
